from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Main pattern fit: matching terminal runs, or long shifted suffix patterns.
    for r, row in enumerate(grid):
        last = max((c for c, v in enumerate(row) if v != bg), default=-1)
        if last < 0 or last == w - 1:
            continue
        start_run = last
        while start_run > 0 and row[start_run - 1] == row[last]:
            start_run -= 1
        run_len = last - start_run + 1
        found = False
        for t, ref in enumerate(grid):
            if t == r:
                continue
            if run_len >= 2:
                if ref[start_run:last + 1] == row[start_run:last + 1] and all(v != bg for v in ref[last + 1:]):
                    found = True
                    break
            else:
                for a in range(last + 1):
                    length = last - a + 1
                    for s in range(a):
                        e = s + length
                        if length >= 5 and e <= w and ref[s:e] == row[a:last + 1] and e < w and all(v != bg for v in ref[e:]):
                            found = True
                            break
                    if found:
                        break
                if found:
                    break
        if found:
            for c in range(last + 1, w):
                out[r][c] = 1
    # Partial prefix fit: mark only the continued foreground footprint in a reference row.
    starts = [next((c for c, x in enumerate(row) if x != bg), w) for row in grid]
    for r, row in enumerate(grid):
        if starts[r] == w:
            continue
        last = max(c for c, x in enumerate(row) if x != bg)
        cut = last + 1
        if cut == w:
            continue
        terminal = row[last]
        run_start = last
        while run_start > 0 and row[run_start - 1] == terminal:
            run_start -= 1
        if last - run_start + 1 < 2:
            continue
        opts = []
        for t, ref in enumerate(grid):
            if t == r or starts[t] == w:
                continue
            if t > r:
                if starts[t] != starts[r] or not all(x != bg for x in ref[cut:]):
                    continue
            else:
                if starts[r] == 0:
                    if starts[t] != 0:
                        continue
                elif abs(starts[t] - starts[r]) > 2:
                    continue
            for s in range(cut):
                if row[s] != ref[s]:
                    continue
                e = s
                while e + 1 < cut and row[e + 1] == ref[e + 1]:
                    e += 1
                if e == cut - 1 and any(x != bg for x in ref[cut:]):
                    opts.append((sum(x != bg for x in ref[cut:]), e - s + 1, ref))
        if opts:
            ref = max(opts, key=lambda x: (x[0], x[1]))[2]
            for c in range(cut, w):
                if ref[c] != bg:
                    out[r][c] = 1
    return out

